<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8"><title>{{ $chart->titulo }}</title><style>body{font-family:DejaVu Sans,Arial,sans-serif;color:#1e293b;padding:32px}h1{font-size:22px;margin-bottom:24px}.bar{height:260px;border-bottom:1px solid #94a3b8;display:flex;align-items:end;gap:18px}.item{flex:1;text-align:center;font-size:10px}.column{margin:auto;width:40px;background:{{ $chart->cor }};min-height:2px}.value{font-weight:bold;margin-bottom:4px}table{width:100%;border-collapse:collapse;margin-top:28px}th,td{padding:8px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:12px}th{background:#f8fafc}</style></head><body><h1>{{ $chart->titulo }}</h1><div class="bar">@php($max = max(1, max($data['values'] ?: [0])))@foreach($data['values'] as $index => $value)<div class="item"><div class="value">{{ $value }}</div><div class="column" style="height:{{ ($value / $max) * 220 }}px"></div><div>{{ $data['labels'][$index] }}</div></div>@endforeach</div><table><thead><tr><th>Categoria</th><th>Valor</th></tr></thead><tbody>@foreach($data['labels'] as $index => $label)<tr><td>{{ $label }}</td><td>{{ $data['values'][$index] }}</td></tr>@endforeach</tbody></table></body></html>
